const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 5) {
  return [{
    json: {
      error: true,
      message: "❌ Missing information. Please provide all 5 items."
    }
  }];
}

return [{
  json: {
    error: false,
    business: lines[0],
    campaign_goal: lines[1],
    target_audience: lines[2],
    offer_message: lines[3],
    call_to_action: lines[4],
    created_at: new Date().toISOString()
  }
}];

