// Parse email campaign
const emailContent = items[0].json.candidates[0].content.parts[0].text;
const campaignData = $node["Parse Campaign Details"].json;

// Extract subject line
const subjectMatch = emailContent.match(/SUBJECT:\s*(.+?)\n/);
const altSubjectMatch = emailContent.match(/ALT SUBJECT:\s*(.+?)\n/);
const subject = subjectMatch ? subjectMatch[1].trim() : 'Your Campaign';
const altSubject = altSubjectMatch ? altSubjectMatch[1].trim() : '';

// Extract body (everything after alt subject line)
const bodyStart = emailContent.indexOf('ALT SUBJECT:');
const bodyContent = bodyStart >= 0 ? emailContent.substring(bodyStart).split('\n').slice(2).join('\n').trim() : emailContent;

return [{
  json: {
    ...campaignData,
    subject_line: subject,
    alt_subject_line: altSubject,
    email_body: bodyContent,
    generated_at: new Date().toISOString()
  }
}];

