// Format follow-up list
const customers = items.map(i => i.json);

if (customers.length === 0) {
  return [{
    json: {
      message: "📭 No customers for follow-up at this time"
    }
  }];
}

let message = `📧 **Follow-up Campaign Candidates**\n`;
message += `${customers.length} recent customers\n\n`;

for (const customer of customers.slice(0, 10)) {
  const completedDate = new Date(customer.completed_at).toLocaleDateString();
  message += `👤 ${customer.customer_name}\n`;
  message += `   📦 ${customer.product_type} (${completedDate})\n`;
  message += `   📧 ${customer.customer_email}\n\n`;
}

if (customers.length > 10) {
  message += `... and ${customers.length - 10} more\n\n`;
}

message += `**Suggested Actions:**\n`;
message += `1. Send satisfaction survey\n`;
message += `2. Request review/testimonial\n`;
message += `3. Offer repeat customer discount\n`;
message += `4. Share new product line\n\n`;
message += `Reply with action number to generate campaign.`;

return [{
  json: {
    message: message,
    customer_count: customers.length,
    customers: customers
  }
}];

// Format campaign analytics
const analytics = items.map(i => i.json);

if (analytics.length === 0) {
  return [{
    json: {
      message: "📭 No campaign data available yet"
    }
  }];
}

let message = `📊 **Marketing Campaign Analytics**\nLast 90 Days\n\n`;

let totalSent = 0;
let totalOpened = 0;
let totalClicks = 0;

for (const data of analytics) {
  const sent = parseInt(data.total_sent || 0);
  const opened = parseInt(data.total_opened || 0);
  const clicks = parseInt(data.total_clicks || 0);
  const openRate = parseFloat(data.avg_open_rate || 0);
  const clickRate = parseFloat(data.avg_click_rate || 0);

  message += `**${data.campaign_goal.toUpperCase()}**\n`;
  message += `📧 Sent: ${sent}\n`;
  message += `👁️ Opened: ${opened} (${openRate.toFixed(1)}%)\n`;
  message += `👆 Clicks: ${clicks} (${clickRate.toFixed(1)}%)\n\n`;

  totalSent += sent;
  totalOpened += opened;
  totalClicks += clicks;
}

const overallOpenRate = totalSent > 0 ? (totalOpened / totalSent * 100).toFixed(1) : 0;
const overallClickRate = totalSent > 0 ? (totalClicks / totalSent * 100).toFixed(1) : 0;

message += `**OVERALL PERFORMANCE**\n`;
message += `📧 Total Sent: ${totalSent}\n`;
message += `👁️ Open Rate: ${overallOpenRate}%\n`;
message += `👆 Click Rate: ${overallClickRate}%\n\n`;

if (parseFloat(overallOpenRate) > 20) {
  message += `✅ Open rate is good!\n`;
} else {
  message += `⚠️ Consider improving subject lines\n`;
}

if (parseFloat(overallClickRate) > 3) {
  message += `✅ Click rate is strong!`;
} else {
  message += `⚠️ Try stronger CTAs`;
}

return [{
  json: {
    message: message,
    total_sent: totalSent,
    overall_open_rate: parseFloat(overallOpenRate),
    overall_click_rate: parseFloat(overallClickRate)
  }
}];
